/**
 * Base channel catalogue: loading, validation and lookups.
 *
 * Single logical catalogue, stored as JSON split by origin under
 * `data/channels/`: `base.json` (the hand-curated catalogue) plus
 * `ca.json` / `fr.json` / `us.json` (generated by
 * `scripts/import-iptv-org.mjs` from the iptv-org country playlists —
 * regenerate those files with the script, never edit them by hand).
 * To add or edit a curated channel, edit `base.json` only — never add
 * channel data back into TypeScript. Each JSON entry matches the
 * `Channel` type (see `lib/channel-types.ts`); see `data/README.md`
 * for the field-by-field schema.
 *
 * This module is the only place that reads the JSON file. At load time it:
 *   1. validates every entry (required fields, id format, HTTPS URLs —
 *      with one exception: an http `stream` explicitly flagged
 *      `insecureStream`, see `validateChannel`),
 *   2. deduplicates by id (first occurrence wins, matching the behaviour
 *      of the former `Array.prototype.find`-based lookup), and
 *   3. builds `Map` indexes so lookups by id, category, region and legacy
 *      source list are O(1)-ish instead of repeated linear scans of the
 *      whole catalogue on every render.
 *
 * Logo URLs (`logoUrl`) were merged into the JSON from the former
 * `lib/channel-logos.ts` map (source: iptv-org/database). No logo URL is
 * ever synthesized from a slug; channels without one keep the UI's text
 * fallback (`brand`).
 */

import baseChannelsJson from '../data/channels/base.json';
import caChannelsJson from '../data/channels/ca.json';
import frChannelsJson from '../data/channels/fr.json';
import usChannelsJson from '../data/channels/us.json';
import type { Channel, ChannelResolver } from './channel-types';

/**
 * The catalogue files, in display order: curated base first, then the
 * iptv-org imports by country. Parsed once at module load (server-side);
 * the per-file split keeps each file reviewable in a diff and lets the
 * import script regenerate only its own outputs.
 */
const rawChannels: unknown[] = [
  ...(baseChannelsJson as unknown[]),
  ...(caChannelsJson as unknown[]),
  ...(frChannelsJson as unknown[]),
  ...(usChannelsJson as unknown[]),
];

export type {
  Channel,
  ChannelLanguage,
  ChannelRegion,
  ChannelResolver,
  ChannelSource,
} from './channel-types';

const REGIONS: Channel['region'][] = ['Québec', 'Canada', 'France', 'USA', 'International'];
const LANGUAGES: NonNullable<Channel['language']>[] = ['fr', 'en', 'zxx'];
const RESOLVERS: ChannelResolver[] = [
  'telequebec',
  'cpac',
  'france24',
  'youtube',
  'tfo',
  'public-senat',
];
const REQUIRED_STRING_FIELDS = [
  'id',
  'name',
  'brand',
  'region',
  'category',
  'color',
  'description',
  'official',
  'guide',
] as const;
const URL_FIELDS = [
  'official',
  'guide',
  'stream',
  'embed',
  'youtube',
  'directory',
  'logoUrl',
] as const;
const ID_PATTERN = /^[a-z0-9][a-z0-9-]{0,79}$/;
const COLOR_PATTERN = /^#[0-9a-f]{6}$/i;

/**
 * Validate one raw JSON entry and return it as a `Channel`.
 * Throws on malformed data: bad catalogue data is a build-time bug and
 * must fail loudly instead of silently shipping a broken channel card.
 * Note that a playable source (stream/embed/resolve) is NOT required:
 * paid channels are listed as official-link-only entries (e.g. `ici-tele`).
 */
function validateChannel(raw: unknown, index: number): Channel {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error(`channel catalogue: entry #${index} is not an object`);
  }
  const channel = raw as Record<string, unknown>;
  for (const field of REQUIRED_STRING_FIELDS) {
    if (typeof channel[field] !== 'string' || !(channel[field] as string).trim()) {
      throw new Error(`channel catalogue: entry #${index} is missing "${field}"`);
    }
  }
  const id = channel.id as string;
  if (!ID_PATTERN.test(id)) {
    throw new Error(`channel catalogue: invalid channel id "${id}"`);
  }
  if (!REGIONS.includes(channel.region as Channel['region'])) {
    throw new Error(`channel catalogue: channel "${id}" has an unknown region`);
  }
  if (!COLOR_PATTERN.test(channel.color as string)) {
    throw new Error(`channel catalogue: channel "${id}" has an invalid color`);
  }
  if (channel.language !== undefined && !LANGUAGES.includes(channel.language as never)) {
    throw new Error(`channel catalogue: channel "${id}" has an unknown language`);
  }
  if (channel.resolve !== undefined && !RESOLVERS.includes(channel.resolve as never)) {
    throw new Error(`channel catalogue: channel "${id}" has an unknown resolver`);
  }
  for (const field of URL_FIELDS) {
    const value = channel[field];
    if (value === undefined) continue;
    if (typeof value !== 'string') {
      throw new Error(`channel catalogue: channel "${id}" field "${field}" is not a URL string`);
    }
    const url = new URL(value);
    // Sole exception to the HTTPS rule: an http `stream` explicitly
    // flagged `insecureStream` — the player warns the viewer and explains
    // the browser setting that unblocks it. Every other URL must be https.
    const insecureHttpStream = field === 'stream'
      && url.protocol === 'http:'
      && channel.insecureStream === true;
    if ((url.protocol !== 'https:' && !insecureHttpStream) || url.username || url.password) {
      throw new Error(`channel catalogue: channel "${id}" field "${field}" must be a public HTTPS URL`);
    }
  }
  if (channel.insecureStream !== undefined
    && (typeof channel.insecureStream !== 'boolean'
      || (channel.insecureStream
        && !(typeof channel.stream === 'string' && channel.stream.startsWith('http://'))))) {
    throw new Error(`channel catalogue: channel "${id}" has an invalid "insecureStream" flag`);
  }
  return channel as unknown as Channel;
}

/** Load, validate and deduplicate the catalogue (first id wins). */
function loadChannels(): Channel[] {
  const seen = new Set<string>();
  const loaded: Channel[] = [];
  (rawChannels as unknown[]).forEach((raw, index) => {
    const channel = validateChannel(raw, index);
    if (seen.has(channel.id)) return;
    seen.add(channel.id);
    loaded.push(channel);
  });
  return loaded;
}

/** All base channels, in catalogue order. */
export const channels: Channel[] = loadChannels();

/** O(1) lookup by channel id. */
export const channelsById: ReadonlyMap<string, Channel> = new Map(
  channels.map((channel) => [channel.id, channel]),
);

/** Channels grouped by category, in catalogue order within each group. */
export const channelsByCategory: ReadonlyMap<string, Channel[]> = groupBy(
  channels,
  (channel) => channel.category,
);

/** Channels grouped by region, in catalogue order within each group. */
export const channelsByRegion: ReadonlyMap<string, Channel[]> = groupBy(
  channels,
  (channel) => channel.region,
);

/** Ids of the channels that used to live in `lib/expanded-catalogue.ts`. */
export const expandedChannelIds: ReadonlySet<string> = new Set(
  channels.filter((channel) => channel.source === 'expanded').map((channel) => channel.id),
);

/** Ids of the channels that used to live in `lib/catalogue.ts`. */
export const additionalChannelIds: ReadonlySet<string> = new Set(
  channels.filter((channel) => channel.source === 'additional').map((channel) => channel.id),
);

function groupBy(list: Channel[], key: (channel: Channel) => string): Map<string, Channel[]> {
  const groups = new Map<string, Channel[]>();
  for (const channel of list) {
    const groupKey = key(channel);
    const group = groups.get(groupKey);
    if (group) group.push(channel);
    else groups.set(groupKey, [channel]);
  }
  return groups;
}

/** Find a channel by id, or `undefined` when it is not in the catalogue. */
export const channelById = (id: string): Channel | undefined => channelsById.get(id);

export const languageLabel = (channel: Channel): string =>
  channel.language === 'en'
    ? 'Anglais'
    : channel.language === 'zxx'
      ? 'Sans paroles'
      : 'Français';
